import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.DbSlGjul.js";const u=JSON.parse('{"title":"Data collection with DataHive","description":"Collect, annotate, validate, and share HiveBoard learning episodes with DataHive, including data collected during benchmark evaluations.","frontmatter":{"description":"Collect, annotate, validate, and share HiveBoard learning episodes with DataHive, including data collected during benchmark evaluations."},"headers":[],"relativePath":"guides/datahive.md","filePath":"guides/datahive.md","lastUpdated":1789952401000}'),n={name:"guides/datahive.md"};function s(r,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="data-collection-with-datahive" tabindex="-1">Data collection with DataHive <a class="header-anchor" href="#data-collection-with-datahive" aria-label="Permalink to &quot;Data collection with DataHive&quot;">​</a></h1><p><a href="https://github.com/hiveboard-bench/DataHive" target="_blank" rel="noreferrer">DataHive</a> is a toolkit for collecting HiveBoard manipulation episodes with robot states, control commands, camera recordings, and task annotations. It provides a local browser interface, a Python recording API, validation tools, and upload to a configured Hugging Face dataset repository.</p><p><strong>We encourage labs to collect learning data while running a benchmark evaluation.</strong> Recording the same trials can provide both performance measurements and trajectories for subsequent research. Dataset collection is optional: a benchmark submission still requires all 13 conditions with five trials each, while the <a href="/hivedocs/contribute/evaluations">learning-dataset call</a> has no fixed episode count or requirement to cover every condition.</p><h2 id="choose-the-workflow" tabindex="-1">Choose the workflow <a class="header-anchor" href="#choose-the-workflow" aria-label="Permalink to &quot;Choose the workflow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th><th>Output</th></tr></thead><tbody><tr><td><a href="/hivedocs/benchmark/evaluation-runner">Website Evaluation Runner</a></td><td>Time trials, enter outcomes, and prepare a benchmark submission in the browser</td><td>Benchmark trial CSV, platform description, and submission package</td></tr><tr><td>DataHive local Runner and Annotate pages</td><td>Organize collection sessions, connect recorded states, commands, and videos to trials, and annotate and validate episodes</td><td>HDF5 episodes, camera MP4 files, and an extended annotation CSV</td></tr></tbody></table><p>The website Evaluation Runner does not acquire robot or camera streams. DataHive requires a recording integration with your experimental system; installing the toolkit alone does not connect it to a robot.</p><h2 id="install-and-configure" tabindex="-1">Install and configure <a class="header-anchor" href="#install-and-configure" aria-label="Permalink to &quot;Install and configure&quot;">​</a></h2><p>Use Python 3.10 or later in a dedicated environment. Install the video extra so validation can inspect the recordings:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;datahive-tools[video]&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_HF_NAMESPACE/YOUR_DATASET</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-profile</span></span></code></pre></div><p>Replace the repository placeholder with an existing <strong>private Hugging Face dataset repository</strong> that your lab can write to. <code>init</code> prompts for a lab identifier and Hugging Face token; it saves the configuration locally and does not create the remote repository or set its visibility. Register your laboratory using the <a href="https://docs.google.com/forms/d/e/1FAIpQLScfDJvfcweYjv8bLDEALWOJk1q4mW3xOeB52aUey1VWWp_pxQ/viewform?usp=dialog" target="_blank" rel="noreferrer">DataHive Lab Registration Form</a> to receive your designated <code>lab_id</code> and token. If the organizers have arranged a repository for your lab, use that destination. Without <code>--repo-id</code>, DataHive defaults to <code>HiveBoard/&lt;lab_id&gt;</code>.</p><p>Fill in <code>samples/robot_profile.yaml</code> before recording. Describe the robot, end-effector, control mode, state and command conventions, joint order, recording rate, and cameras. See the upstream <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-data-prep/reference/robot-profile.md" target="_blank" rel="noreferrer">robot-profile reference</a> for field definitions.</p><p>From the same working directory, start the interface:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interface</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Open <code>http://127.0.0.1:8000</code> on that computer. Use <strong>Runner</strong> to plan a session or <strong>Annotate</strong> to inspect existing episodes.</p><h2 id="record-a-session" tabindex="-1">Record a session <a class="header-anchor" href="#record-a-session" aria-label="Permalink to &quot;Record a session&quot;">​</a></h2><p>Select the task conditions and collection mode. The Runner defaults to five trials per selected condition. Dataset collections can use a subset of conditions and additional sessions; the benchmark&#39;s 65-trial requirement is not a dataset-size limit.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Recording procedure</th></tr></thead><tbody><tr><td>Manual</td><td>Use the countdown and stopwatch, enter the outcome, and attach the HDF5 episode and one MP4 per camera listed in the robot profile. Your experimental system records these files.</td></tr><tr><td>Automatic</td><td>Connect your recording/control script through <code>CollectClient</code>. The script receives the queued task, writes states and commands through <code>EpisodeWriter</code>, attaches camera recordings, and returns the episode for annotation. The evaluator still determines the outcome.</td></tr></tbody></table><p>Follow the upstream <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-data-prep/reference/layout-and-format.md" target="_blank" rel="noreferrer">data format</a> when preparing files. For automatic collection, use the <a href="https://github.com/hiveboard-bench/DataHive/blob/main/src/datahive/skills/datahive-auto-collect/reference/adapting.md" target="_blank" rel="noreferrer">robot integration guide</a>. Robot drivers, command generation, and camera acquisition remain part of the lab&#39;s integration.</p><p><strong>Record physical trials with an external camera</strong>, with the board, end-effector, and task state visible throughout. Include that camera in the profile when storing its recording with the DataHive episode. For simulation, record rendered camera observations and identify the simulator and configuration.</p><h3 id="check-the-recording-setup-first" tabindex="-1">Check the recording setup first <a class="header-anchor" href="#check-the-recording-setup-first" aria-label="Permalink to &quot;Check the recording setup first&quot;">​</a></h3><p>DataHive currently expects aligned state and command arrays in HDF5, a proprioception rate of at least 100 Hz, and one MP4 per configured camera. Its video checks require matching camera resolution, frame rate, and frame count; each image dimension must be 180–1280 pixels, and video duration must match the episode within 0.5 seconds. Check the upstream format reference when choosing acquisition settings.</p><p>Record and validate a short pilot episode before starting the collection. Preserve the original streams and timestamps and document any conversion. If your system cannot meet these constraints, discuss an alternative format with the organizers before collection. The dataset call also welcomes depth, force/torque, tactile, and other signals; agree on supplemental files for modalities outside DataHive&#39;s current episode format.</p><h2 id="annotate-and-validate" tabindex="-1">Annotate and validate <a class="header-anchor" href="#annotate-and-validate" aria-label="Permalink to &quot;Annotate and validate&quot;">​</a></h2><p>The local interface supports review and validation. The equivalent command sequence for an existing episode is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> annotate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span></code></pre></div><p>Replace <code>EPISODE_ID</code> with the recorded episode identifier. <code>check</code> inspects recording integrity before annotation. <code>annotate</code> records task outcome and related fields; <code>validate</code> checks the episode and annotation together. Inspect both errors and warnings.</p><p>Use the <a href="/hivedocs/benchmark/tasks">task definitions</a> and <a href="/hivedocs/benchmark/logging">counting conventions</a> for outcomes, stages, attempts, and regrasps. Preserve unsuccessful episodes and label interventions, resets, and aborted recordings. A benchmark trial may contain several attempts or regrasps; these do not become separate scored trials.</p><h2 id="collect-during-a-benchmark-evaluation" tabindex="-1">Collect during a benchmark evaluation <a class="header-anchor" href="#collect-during-a-benchmark-evaluation" aria-label="Permalink to &quot;Collect during a benchmark evaluation&quot;">​</a></h2><ol><li>Test recording and synchronization before the scored trials. Keep familiarization and training episodes identifiable and separate from the evaluation set.</li><li>Follow the <a href="/hivedocs/benchmark/protocol">evaluation protocol</a>, including all 13 conditions, five trials per condition, fixed control settings, neutral starting poses, resets, and task timeouts. Use the required separate blocks for the two ball-valve configurations.</li><li>Record the same trial&#39;s states, commands, and camera streams. Maintain an index linking its DataHive session and episode IDs to the benchmark <code>trial_id</code> and <code>attachment_id</code>; session trial numbers may follow a different order from the benchmark template.</li><li>Time the benchmark trial from the first commanded task motion until success, a safety stop, or timeout. Save a completion time only for successful trials. A recording may include time before or after the task, so its total duration is not automatically the benchmark completion time.</li><li>Prepare the benchmark log and <a href="/hivedocs/benchmark/results">submission package</a> separately from the learning dataset. Report every scored trial, including failures, and retain the external-camera recording for each one.</li></ol><p>DataHive&#39;s <code>trials.csv</code> contains extra annotation fields and is <strong>not a drop-in replacement for the benchmark CSV</strong>. For the benchmark submission, use the website Evaluation Runner or transfer the scored results into the <a href="/hivedocs/benchmark/logging">benchmark template</a>, preserving its condition-to-trial mapping and filling all required counts and stages. Keep a correspondence to the original episode IDs. Do not copy DataHive&#39;s operator and annotator names into the public benchmark files.</p><p>To generate the benchmark submission ZIP, enter the scored results and platform details in the website Evaluation Runner. It does not currently import DataHive CSV files. The template can be used to prepare the records before entry.</p><p>Passing DataHive validation checks an episode&#39;s format and annotations; it does not establish that all 65 benchmark trials or the full evaluation protocol have been completed. Data collected during evaluation can be contributed for future training, but must remain excluded from training or tuning the policy whose performance those trials report.</p><h2 id="upload-and-submit-for-review" tabindex="-1">Upload and submit for review <a class="header-anchor" href="#upload-and-submit-for-review" aria-label="Permalink to &quot;Upload and submit for review&quot;">​</a></h2><p>After validation, upload an episode to the configured dataset repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">datahive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EPISODE_ID</span></span></code></pre></div><p>Uploading stores the data at that destination; it does not send an organizer-review request. Keep the repository private during review, provide the setup description, calibration, episode index, and loading example, and follow the <a href="/hivedocs/contribute/evaluations#send-the-data-for-review">dataset submission instructions</a>. Arrange access with the organizers and include any supplemental sensor files in the shared package.</p><p>Record the DataHive package version or commit with the dataset. DataHive builds on the architecture and workflows of <a href="https://github.com/oopsie-data" target="_blank" rel="noreferrer">Oopsie Data</a>; see its <a href="https://github.com/hiveboard-bench/DataHive#readme" target="_blank" rel="noreferrer">README</a> for project credits and current usage.</p>`,37)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
